// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 100 ether);
    }

    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != msg.sender);
        vm.assume(nonOwner != address(0));
        amount = bound(amount, 1, address(c).balance);

        vm.prank(nonOwner);
        bool ok;
        try c.sendTo(address(0x1234), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Send from non-owner must revert in reference");
    }
}
